SELECT
    (SELECT COUNT(*) FROM Addresses) AS total_addresses,
    (SELECT COUNT(*) FROM Customers WHERE customer_address LIKE '%California%') AS total_customers_in_california;

SELECT
  (SELECT COUNT(*) FROM "Addresses") AS address_count,
  (SELECT COUNT(*) FROM "Customers" WHERE "customer_address" LIKE '%, CA %' OR "customer_address" LIKE '%, CA') AS california_customer_count;

SELECT 
    (SELECT COUNT(*) FROM Addresses WHERE address_details LIKE '%California%') AS address_count,
    (SELECT COUNT(*) FROM Customers WHERE customer_address LIKE '%California%') AS customer_count;

SELECT (
    (SELECT COUNT(*) FROM "Addresses" WHERE "address_details" LIKE '% CA %') +
    (SELECT COUNT(*) FROM "Customers" c JOIN "Addresses" a ON c."address_id" = a."address_id" WHERE a."address_details" LIKE '% CA %')
) AS "total";

